    <!-- Enhanced manifest with better iOS support -->
    <link rel="manifest" href="data:application/manifest+json,%7B%22name%22%3A%22JadedLight%20-%20AI%20Chat%22%2C%22short_name%22%3A%22JadedLight%22%2C%22description%22%3A%22Egyszer%C5%B1%20%C3%A9s%20gyors%20AI%20chat%20alkalmaz%C3%A1s%22%2C%22start_url%22%3A%22%2F%22%2C%22display%22%3A%22standalone%22%2C%22orientation%22%3A%22portrait-primary%22%2C%22theme_color%22%3A%22%23000000%22%2C%22background_color%22%3A%22%23000000%22%2C%22scope%22%3A%22%2F%22%2C%22lang%22%3A%22hu%22%2C%22categories%22%3A%5B%22productivity%22%2C%22utilities%22%5D%2C%22prefer_related_applications%22%3Afalse%2C%22icons%22%3A%5B%7B%22src%22%3A%22data%3Aimage%2Fsvg%2Bxml%2C%253Csvg%20xmlns%3D%27http%3A%2F%2F">
    <link rel="stylesheet" href="" xintegrity="sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="no-referrer">
    <style>
        @charset "utf-8";
        @import url('');
        :root {
            --primary: #39FF14; --secondary: #0A61F7; --accent: #0A61F7;
            --border-glow: rgba(57, 255, 20, 0.5); --primary-rgb: 57, 255, 20;
            --bg: #000000; --surface: rgba(10, 10, 10, 0.6); --glass: rgba(255, 255, 255, 0.03);
            --glass-strong: rgba(255, 255, 255, 0.06); --border: rgba(255, 255, 255, 0.1);
            --text: #f1f5f9; --text-muted: #94a3b8; --radius-lg: 20px; --radius-md: 14px;
            --radius-sm: 10px; --shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
            --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1); --transition-color: 20s ease-in-out;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
        html { height: 100%; height: -webkit-fill-available; scroll-behavior: smooth; touch-action: manipulation; }
        body {
            font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text);
            min-height: 100vh; min-height: -webkit-fill-available; overflow: hidden;
            -webkit-font-smoothing: antialiased; font-size: 15px; overscroll-behavior: none;
        }
        .aurora-background { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: -1; }
        .aurora { position: absolute; border-radius: 50%; mix-blend-mode: screen; filter: blur(140px); opacity: 0; transition: background-color 20s ease-in-out, opacity 12s ease-in-out; animation: pulse 45s ease-in-out infinite alternate; }
        .aurora.visible { opacity: 0.25; }
        .aurora.one { width: 80vmax; height: 80vmax; animation-name: move-one, pulse; animation-duration: 240s, 50s; animation-timing-function: ease-in-out, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
        .aurora.two { width: 70vmax; height: 70vmax; animation-name: move-two, pulse; animation-duration: 210s, 55s; animation-timing-function: ease-in-out, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
        @keyframes move-one { from { transform: translate(-20vw, -20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes move-two { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(-10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
        .container { display: flex; flex-direction: column; min-height: 100vh; min-height: -webkit-fill-available; overflow: hidden; }
        .header { padding: 8px 12px; height: 48px; background: var(--surface); backdrop-filter: blur(40px) saturate(180%); border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0; z-index: 100; }
        .header-title { font-size: 1rem; font-weight: 600; background: linear-gradient(135deg, var(--primary), var(--secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; text-shadow: 0 0 20px var(--border-glow); position: absolute; left: 50%; transform: translateX(-50%); }
        .header-btn { width: 36px; height: 36px; border-radius: 50%; border: none; background: transparent; color: var(--text-muted); font-size: 1rem; cursor: pointer; transition: all 0.2s; display: flex; align-items: center; justify-content: center; }
        .header-btn:hover { background: var(--glass-strong); color: var(--text); }
        .chat-area { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
        .messages-container { padding: 12px; overflow-y: auto; flex: 1; max-height: calc(100vh - 96px); }
        .welcome-screen { text-align: center; max-width: 500px; margin: 0 auto; padding: 30px 20px; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; animation: fadeIn 1s var(--transition-curve); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .welcome-title { font-size: 2.2rem; font-weight: 800; background: linear-gradient(135deg, var(--primary), var(--secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 0.5rem; }
        .welcome-subtitle { font-size: 0.9rem; line-height: 1.5; margin-bottom: 1.2rem; color: var(--text-muted); }
        .start-btn { padding: 10px 20px; font-size: 0.9rem; min-height: 42px; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-md); color: var(--text); font-weight: 600; cursor: pointer; transition: all 0.2s var(--transition-curve); display: inline-flex; align-items: center; gap: 8px; }
        .start-btn:hover { border-color: var(--border-glow); transform: translateY(-2px) scale(1.03); }
        .message { margin-bottom: 20px; animation: messageSlideIn 0.4s var(--transition-curve); user-select: none; -webkit-user-select: none; }
        @keyframes messageSlideIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .user-message { display: flex; justify-content: flex-end; }
        .user-bubble { color: #fff; padding: 10px 14px; border-radius: var(--radius-lg) var(--radius-lg) var(--radius-sm) var(--radius-lg); max-width: 80%; font-weight: 500; font-size: 0.9rem; line-height: 1.4; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3); background: linear-gradient(135deg, var(--primary), var(--secondary)); cursor: pointer; }
        .ai-message { display: flex; flex-direction: column; max-width: 90%; }
        .ai-bubble { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-lg) var(--radius-lg) var(--radius-lg) var(--radius-sm); padding: 10px 14px; line-height: 1.5; font-size: 0.9rem; white-space: pre-wrap; word-wrap: break-word; cursor: pointer; }
        .input-area { padding: 8px 12px; background: rgba(5, 2, 10, 0.6); backdrop-filter: blur(30px) saturate(150%); border-top: 1px solid var(--border); position: sticky; bottom: 0; z-index: 50; flex-shrink: 0; }
        @supports (padding: max(0px)) { .input-area { padding-bottom: max(8px, env(safe-area-inset-bottom)); } }
        .input-wrapper { display: flex; gap: 8px; align-items: flex-end; }
        .message-input { flex: 1; background: var(--glass-strong); border: 1px solid var(--border); border-radius: 20px; padding: 10px 14px; color: var(--text); font-size: 0.9rem; resize: none; outline: none; transition: all 0.2s var(--transition-curve); min-height: 40px; max-height: 140px; font-family: inherit; line-height: 1.4; }
        .message-input:focus { border-color: var(--primary); box-shadow: 0 0 15px -2px var(--primary); }
        .send-btn-container { width: 40px; height: 40px; flex-shrink: 0; }
        .send-btn { width: 100%; height: 100%; border-radius: 50%; cursor: pointer; display: flex; align-items: center; justify-content: center; border: none; background: var(--primary); color: white; transition: all 0.2s var(--transition-curve); font-size: 0.9rem; }
        .send-btn:disabled { background: var(--glass-strong); color: var(--text-muted); cursor: not-allowed; }
        .send-btn:not(:disabled):hover { transform: scale(1.08); box-shadow: 0 0 15px var(--primary); }
        .ai-bubble pre { background-color: rgba(0,0,0,0.3); border-radius: var(--radius-sm); padding: 10px; margin: 10px 0; font-family: 'Courier New', Courier, monospace; font-size: 0.85em; white-space: pre-wrap; word-wrap: break-word; position: relative; }
        .ai-bubble code { font-family: 'Courier New', Courier, monospace; background-color: rgba(255,255,255,0.1); padding: 2px 5px; border-radius: 4px; }
        .ai-bubble pre > code { background-color: transparent; padding: 0; }
        .copy-code-btn { position: absolute; top: 6px; right: 6px; background: var(--glass-strong); border: 1px solid var(--border); color: var(--text-muted); padding: 3px 7px; border-radius: 5px; cursor: pointer; font-size: 0.75em; transition: all 0.2s; opacity: 0.5; }
        .ai-bubble pre:hover .copy-code-btn { opacity: 1; }
        .copy-code-btn:hover { background: var(--primary); color: white; border-color: var(--primary); }

        /* --- ÚJ: Keresési állapot és források stílusai --- */
        .search-status { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 8px; display: flex; align-items: center; gap: 8px; animation: fadeIn 0.5s; }
        .search-status .fa-spin { font-size: 0.7rem; }
        .sources-container { margin-top: 12px; border-top: 1px solid var(--border); padding-top: 8px; }
        .sources-title { font-size: 0.75rem; font-weight: 600; color: var(--text-muted); margin-bottom: 6px; }
        .source-link { display: block; font-size: 0.8rem; color: var(--primary); text-decoration: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 4px; transition: color 0.2s; }
        .source-link:hover { color: var(--secondary); }

        /* --- MÓDOSÍTVA: A másolás gomb stílusai és a PWA viewport -- */
        #copyOverlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; display: flex; align-items: center; justify-content: center; background-color: rgba(0, 0, 0, 0.4); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); z-index: 200; opacity: 0; pointer-events: none; transition: opacity 0.3s var(--transition-curve); }
        #copyOverlay.visible { opacity: 1; pointer-events: all; }
        #copyBtn { padding: 16px 32px; font-size: 1.1rem; font-weight: 600; color: var(--text); background: rgba(255, 255, 255, 0.15); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: var(--radius-md); backdrop-filter: blur(15px); -webkit-backdrop-filter: blur(15px); box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4); cursor: pointer; transform: scale(0.9); transition: transform 0.3s var(--transition-curve), background-color 0.2s; min-height: 48px; min-width: 120px; }
        #copyOverlay.visible #copyBtn { transform: scale(1); }
        #copyBtn:hover { background: rgba(255, 255, 255, 0.25); }
        #copyBtn:active { transform: scale(0.98); }
    </style>
</head>
<body>
    <div class="aurora-background"> <div class="aurora one"></div> <div class="aurora two"></div> </div>
    <div class="container">
        <header class="header">
            <button class="header-btn" id="newChatBtn" title="Új beszélgetés"> <i class="fas fa-plus"></i> </button>
            <h1 class="header-title">JadedLight</h1>
            <div style="width: 36px;"></div>
        </header>
        <div class="chat-area">
            <section class="messages-container" id="messagesContainer" aria-live="polite">
                <header class="welcome-screen" id="welcomeScreen">
                    <h1 class="welcome-title">JadedLight</h1>
                    <p class="welcome-subtitle">Autonóm AI asszisztens webkereséssel.</p>
                    <button class="start-btn" onclick="hideWelcome()"> <i class="fas fa-rocket"></i> Kezdjük! </button>
                </header>
            </section>
            <footer class="input-area">
                <div class="input-wrapper">
                    <textarea class="message-input" id="messageInput" placeholder="Írj egy üzenetet..." rows="1" aria-label="Üzenet beviteli mező"></textarea>
                    <div class="send-btn-container">
                        <button class="send-btn" id="sendBtn" onclick="sendMessage()" aria-label="Üzenet küldése" disabled> <i class="fas fa-paper-plane"></i> </button>
                    </div>
                </div>
            </footer>
        </div>
    </div>
    <div id="copyOverlay"> <button id="copyBtn"><i class="far fa-copy"></i> Másolás</button> </div>

    <script>
        const AppState = { isTyping: false, userId: 'user_' + Math.random().toString(36).substr(2, 9) };
        const API_BASE_URL = '/api';
        const messagesContainer = document.getElementById('messagesContainer');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const newChatBtn = document.getElementById('newChatBtn');
        const copyOverlay = document.getElementById('copyOverlay');
        const copyBtn = document.getElementById('copyBtn');
        let welcomeScreen = document.getElementById('welcomeScreen');

        // A DynamicThemeManager és a legtöbb segédfüggvény változatlan...
        class DynamicThemeManager {
            constructor() {
                this.root = document.documentElement;
                this.auroraBlobs = document.querySelectorAll('.aurora');
                this.colorPairs = [
                    {primary: '#39FF14', secondary: '#0A61F7'}, // Neon zöld és élénk kék - MINDIG ELSŐ!
                    {primary: '#0A61F7', secondary: '#39FF14'}, // Élénk kék és neon zöld
                    {primary: '#39FF14', secondary: '#00FFFF'}  // Neon zöld és ciánkék
                ];
                this.currentIndex = 0;
                this.updateColors(this.colorPairs[0]); // Mindig neon zöld-kék indítás
                setInterval(() => this.cyclePalette(), 90000); // 90 másodperc váltási idő
                setTimeout(() => this.auroraBlobs.forEach(b => b.classList.add('visible')), 500);
            }

            updateColors(pair) {
                const primaryRGB = this.hexToRgb(pair.primary).join(',');
                this.root.style.setProperty('--primary', pair.primary);
                this.root.style.setProperty('--secondary', pair.secondary);
                this.root.style.setProperty('--border-glow', `rgba(${primaryRGB}, 0.5)`);
                this.auroraBlobs.forEach((blob, i) => {
                    blob.style.backgroundColor = i % 2 === 0 ? pair.primary : pair.secondary;
                });
            }

            hexToRgb(hex) {
                let r = 0, g = 0, b = 0;
                if (hex.length == 7) {
                    r = parseInt(hex.substring(1, 3), 16);
                    g = parseInt(hex.substring(3, 5), 16);
                    b = parseInt(hex.substring(5, 7), 16);
                }
                return [r, g, b];
            }

            cyclePalette = () => {
                this.currentIndex = (this.currentIndex + 1) % this.colorPairs.length;
                this.updateColors(this.colorPairs[this.currentIndex]);
            }
        }

        function hideWelcome() { if (welcomeScreen) { welcomeScreen.style.animation = 'fadeOut 0.5s forwards'; setTimeout(() => { if (welcomeScreen) welcomeScreen.style.display = 'none'; welcomeScreen = null; }, 500); } }
        function newChat() { messagesContainer.innerHTML = ''; const newWelcome = document.createElement('header'); newWelcome.className = 'welcome-screen'; newWelcome.id = 'welcomeScreen'; newWelcome.innerHTML = `<h1 class="welcome-title">JadedLight</h1><p class="welcome-subtitle">Autonóm AI asszisztens webkereséssel.</p><button class="start-btn" onclick="hideWelcome()"><i class="fas fa-rocket"></i> Kezdjük!</button>`; messagesContainer.appendChild(newWelcome); welcomeScreen = newWelcome; messageInput.value = ''; messageInput.dispatchEvent(new Event('input')); }

        async function sendMessage() {
            const message = messageInput.value.trim();
            if (!message || AppState.isTyping) return;
            hideWelcome();
            addUserMessage(message);
            messageInput.value = '';
            messageInput.dispatchEvent(new Event('input'));
            AppState.isTyping = true;
            sendBtn.disabled = true;

            const aiBubble = createAiMessageContainer();
            messagesContainer.appendChild(aiBubble.container);
            scrollToBottom();

            try {
                const response = await fetch(`${API_BASE_URL}/chat`, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ message, user_id: AppState.userId })
                });
                if (!response.ok) throw new Error(`Szerverhiba: ${response.status}`);
                await streamResponseToBubble(response, aiBubble);
            } catch (error) {
                aiBubble.content.innerHTML += `<p style="color: #ff5555;"><strong>Hiba:</strong> ${escapeHtml(error.message)}</p>`;
            } finally {
                AppState.isTyping = false;
                sendBtn.disabled = messageInput.value.trim().length === 0;
            }
        }

        // --- MÓDOSÍTVA: Stream feldolgozás meta-üzenetekkel és folyamatos görgetéssel ---
        async function streamResponseToBubble(response, bubbleElements) {
            const { container, content, status } = bubbleElements;
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let buffer = '';
            let isRendering = false;
            let autoScrollInterval = null;

            const render = () => {
                if (!isRendering) return;

                // Meta-üzenetek feldolgozása
                if (buffer.includes('[SEARCHING_WEB]')) {
                    status.innerHTML = `<i class="fas fa-globe fa-spin"></i> Keresés a weben...`;
                    container.insertBefore(status, content);
                    buffer = buffer.replace('[SEARCHING_WEB]\n', '');
                }
                if (buffer.includes('[SOURCES:')) {
                    const sourcesMatch = buffer.match(/\[SOURCES:(.*?)\]\n/);
                    if (sourcesMatch) {
                        const urls = sourcesMatch[1].split(',');
                        displaySources(container, urls);
                        buffer = buffer.replace(sourcesMatch[0], '');
                    }
                }

                content.innerHTML = simpleMarkdown(buffer);
                requestAnimationFrame(render);
            };

            const startAutoScroll = () => {
                autoScrollInterval = setInterval(() => {
                    const targetScroll = messagesContainer.scrollHeight;
                    const currentScroll = messagesContainer.scrollTop;
                    const containerHeight = messagesContainer.clientHeight;

                    if (currentScroll + containerHeight < targetScroll) {
                        messagesContainer.scrollBy({
                            top: 2,
                            behavior: 'auto'
                        });
                    }
                }, 16); // ~60fps sima görgetés
            };

            const stopAutoScroll = () => {
                if (autoScrollInterval) {
                    clearInterval(autoScrollInterval);
                    autoScrollInterval = null;
                }
                scrollToBottom(); // Végső pozicionálás
            };

            const startRendering = () => { 
                if (!isRendering) { 
                    isRendering = true; 
                    requestAnimationFrame(render);
                    startAutoScroll();
                } 
            };

            const stopRendering = () => {
                isRendering = false;
                stopAutoScroll();
                content.innerHTML = simpleMarkdown(buffer); // Final render
                addCopyButtonsToCode(content);
                addLongPressCopy(content);
                if (status && status.parentNode) {
                    status.remove(); // Keresési állapot eltávolítása a végén
                }
            };

            startRendering();

            while (true) {
                const { value, done } = await reader.read();
                if (done) { stopRendering(); break; }
                buffer += decoder.decode(value, { stream: true });
            }
        }

        // --- ÚJ: Források megjelenítése ---
        function displaySources(messageContainer, urls) {
            let sourcesDiv = messageContainer.querySelector('.sources-container');
            if (!sourcesDiv) {
                sourcesDiv = document.createElement('div');
                sourcesDiv.className = 'sources-container';
                const title = document.createElement('div');
                title.className = 'sources-title';
                title.textContent = 'Források';
                sourcesDiv.appendChild(title);
                messageContainer.appendChild(sourcesDiv);
            }
            sourcesDiv.innerHTML += urls.map(url => 
                `${new URL(url).hostname}`
            ).join('');
        }

        function addUserMessage(message) {
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message user-message';
            const bubble = document.createElement('div');
            bubble.className = 'user-bubble';
            bubble.textContent = message;
            messageDiv.appendChild(bubble);
            messagesContainer.appendChild(messageDiv);
            addLongPressCopy(bubble);
            scrollToBottom();
        }

        function createAiMessageContainer() {
            const container = document.createElement('div');
            container.className = 'message ai-message';
            const status = document.createElement('div');
            status.className = 'search-status';
            const content = document.createElement('div');
            content.className = 'ai-bubble';
            container.appendChild(content);
            return { container, content, status };
        }

        // A többi segédfüggvény (addLongPressCopy, simpleMarkdown, stb.) változatlan...
        function addLongPressCopy(element){let pressTimer=null;const start=(e)=>{if(e.target.closest('pre'))return;pressTimer=setTimeout(()=>{navigator.vibrate?.(50);const textToCopy=element.innerText;copyBtn.dataset.text=textToCopy;copyBtn.innerHTML='<i class="far fa-copy"></i> Másolás';copyOverlay.classList.add('visible')},500)};const cancel=()=>{clearTimeout(pressTimer)};element.addEventListener("mousedown",start);element.addEventListener("touchstart",start,{passive:true});element.addEventListener("mouseup",cancel);element.addEventListener("mouseleave",cancel);element.addEventListener("touchend",cancel);element.addEventListener("touchcancel",cancel)}
        function simpleMarkdown(text){let html=escapeHtml(text).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/```(\w*)\n([\s\S]*?)```/g,(match,lang,code)=>`<pre><code class="${lang||''}">${code}</code></pre>`).replace(/`(.*?)`/g,'<code>$1</code>');return html}
        function addCopyButtonsToCode(container){container.querySelectorAll('pre').forEach(pre=>{if(pre.querySelector('.copy-code-btn'))return;const btn=document.createElement('button');btn.className='copy-code-btn';btn.innerHTML='<i class="far fa-copy"></i>';btn.title='Kód másolása';btn.onclick=(e)=>{e.stopPropagation();const code=pre.querySelector('code').innerText;copyToClipboard(code,btn)};pre.appendChild(btn)})}
        function copyToClipboard(text,btnElement){const textArea=document.createElement('textarea');textArea.value=text;document.body.appendChild(textArea);textArea.select();try{document.execCommand('copy');if(btnElement){btnElement.innerHTML='<i class="fas fa-check"></i>';setTimeout(()=>{btnElement.innerHTML='<i class="far fa-copy"></i>'},2000)}}catch(err){if(btnElement)btnElement.innerHTML='<i class="fas fa-times"></i>'}document.body.removeChild(textArea)}
        function escapeHtml(text){const div=document.createElement('div');div.textContent=String(text);return div.innerHTML}
        function scrollToBottom(){messagesContainer.scrollTo({top:messagesContainer.scrollHeight,behavior:'smooth'})}
        function setupEventListeners(){messageInput.addEventListener('input',()=>{sendBtn.disabled=messageInput.value.trim().length===0||AppState.isTyping;messageInput.style.height='auto';messageInput.style.height=`${Math.min(messageInput.scrollHeight,140)}px`});messageInput.addEventListener('keydown',(e)=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();if(!sendBtn.disabled)sendMessage()}});newChatBtn.addEventListener('click',newChat);copyOverlay.addEventListener('click',()=>copyOverlay.classList.remove('visible'));copyBtn.addEventListener('click',(e)=>{e.stopPropagation();copyToClipboard(e.currentTarget.dataset.text,e.currentTarget);setTimeout(()=>copyOverlay.classList.remove('visible'),500)})}
        document.addEventListener('DOMContentLoaded',()=>{new DynamicThemeManager();setupEventListeners();messageInput.focus()});
    </script>
</body>
</html>

